    [Parameter, EditorRequired] public EventCallback<ReferenceModel> OnEntryChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnRemove { get; set; }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }

    private void Update(ChangeEventArgs e, string field)
    {
        var value = e.Value?.ToString() ?? "";
        switch (field)
        {
            case nameof(Entry.Name): Entry.Name = value; break;
            case nameof(Entry.Relationship): Entry.Relationship = value; break;
            case nameof(Entry.Email): Entry.Email = value; break;
            case nameof(Entry.Phone): Entry.Phone = value; break;
        }
        OnEntryChanged.InvokeAsync(Entry);
    }
}

